-- Metadata/counts only, STAGING target must be supplied explicitly to the CLI. No secret values.
begin read only;
set local statement_timeout='15s';
select jsonb_build_object('at',clock_timestamp(),'timezone',current_setting('cron.timezone',true),'versions',(select jsonb_agg(version order by version)from supabase_migrations.schema_migrations),'controls',jsonb_build_object('v2',(select to_jsonb(c)from spot_private.soma_v2_control c),'phase_a',(select to_jsonb(c)from spot_private.retention_phase_a_control c),'legacy_retention_paused',(select paused from spot_private.retention_control),'analytics',(select jsonb_build_object('enabled',enabled,'test_only',test_only)from spot_private.analytics_control),'notifications',(select to_jsonb(c)from spot_private.notification_control c),'ops',(select jsonb_build_object('enabled',enabled,'test_only',test_only,'purge_ready',purge_ready,'email',email_enabled)from spot_private.ops_control),'photo',(select jsonb_build_object('phase',phase,'cleanup',execute_enabled,'scheduler',scheduler_enabled)from spot_private.photo_cutover_control)),'roles',(select jsonb_build_object('admin',count(*)filter(where active and role='ADMIN'),'moderator',count(*)filter(where active and role='MODERATOR'))from spot_private.moderation_roles),'current_photo_missing',(select count(*)from profiles p where not exists(select 1 from storage.objects o where o.bucket_id='profile-photos'and o.name=p.photo_path)),'variant_references_missing',(select count(*)from spot_private.photo_assets a join profiles p on p.photo_path=a.photo_path cross join lateral unnest(array[a.thumbnail_path,a.detail_path])n(path) where n.path is not null and not exists(select 1 from storage.objects o where o.bucket_id='profile-photos'and o.name=n.path)),'photo_writer_states',(select jsonb_agg(to_jsonb(x))from(select state,writer,count(*)n from spot_private.photo_lifecycle_sets group by state,writer)x),'anomalies',(select jsonb_agg(to_jsonb(x))from(select code,count(*)n from spot_private.photo_lifecycle_anomalies where resolved_at is null group by code)x),'phase_a_cron_runs',(select count(*)from cron.job_run_details r join cron.job j using(jobid)where j.jobname='soma-retention-phase-a-staging'),'active_jobs',(select jsonb_agg(jsonb_build_object('name',jobname,'schedule',schedule))from cron.job where active));
rollback;
